 <Field label="Tipo de abastecimento *" wide><Choice value={form.fuelId||''} onChange={v=>set('fuelId',v)} label="Tipo de abastecimento solicitado" options={data?.fuels.filter(f=>f.active&&(!form.equipmentId||data.equipment.find(e=>e.id===form.equipmentId)?.fuel_ids.includes(f.id))).map(f=>({value:f.id,label:f.name}))||[]}/></Field>
